// Test mask geometry emitted by the script for both orientations and varied image sizes/PAR.
for (const upright of [true, false]) {
    for (const rounded of [true, false]) {
        for (const cornerRadius of [0, 24, 10000]) {
            api.configure(ctrl, {...s, upright, rounded, cornerRadius});
            for (const l of layers) {
                const masks = l.property('ADBE Mask Parade');
                assert.equal(masks.effects.length, 1, 'Apply reuses the existing mask');
                const mask = masks.property('RC Rounded Corners');
                assert.equal(mask.maskMode, context.MaskMode.INTERSECT);
                const shape = vm.runInNewContext(mask.property('ADBE Mask Shape').expression, {
                    parent: {effect: n => () => api.control(ctrl, n).value},
                    thisLayer: {source: l.source}, thisComp: comp,
                    createPath: (points, ins, outs, closed) => ({points, ins, outs, closed})
                });
                assert.equal(shape.closed, true);
                const w = l.source.width, h = l.source.height, pa = l.source.pixelAspect / comp.pixelAspect;
                const scale = s.size / Math.max(w * pa, h);
                const r = rounded ? Math.min(cornerRadius, w * pa * scale / 2, h * scale / 2) : 0;
                assert.equal(shape.points.length, r > 0 ? 8 : 4);
                for (const p of shape.points) {
                    assert.ok(p[0] >= 0 && p[0] <= w && p[1] >= 0 && p[1] <= h);
                }
                if (r > 0) {
                    near(shape.points[0][0] * scale * pa, r);
                    near(shape.points[2][1] * scale, r);
                    assert.equal(shape.ins.length, 8);
                    assert.equal(shape.outs.length, 8);
                    // Midpoint of the top-right cubic lies on the intended circular arc.
                    const a = shape.points[1], b = shape.points[2];
                    const mid = a.map((v, axis) => (v + 3 * (v + shape.outs[1][axis]) + 3 * (b[axis] + shape.ins[2][axis]) + b[axis]) / 8);
                    near(Math.hypot((mid[0] - a[0]) * scale * pa, (mid[1] - b[1]) * scale), r);
                } else {
                    assert.deepEqual(Array.from(shape.points[0]), [0, 0]);
                    assert.deepEqual(Array.from(shape.points[2]), [w, h]);
                }
            }
        }
    }
}
