// Every layer must use the same permutation, with reproducible seeds and distinct slots.
api.control(ctrl, 'Radius').numKeys = 0;
function arrangement(seed, shuffle = true, upright = false) {
    api.configure(ctrl, {...s, seed, shuffle, upright, rounded: true});
    return layers.map(l => {
        const rotation = evaluate(ctrl, 'ADBE Rotate Z', 3);
        const p = evaluate(l, 'ADBE Position', 3, rotation);
        near(Math.hypot(...p), s.radius);
        const imageRotation = evaluate(l, 'ADBE Rotate Z', 3, rotation);
        if (upright) near(imageRotation + rotation, 0);
        else {
            // Image top follows its shuffled radial position, before the shared parent rotation.
            const a = (imageRotation - 90) * Math.PI / 180;
            near(Math.cos(a), p[0] / s.radius);
            near(Math.sin(a), p[1] / s.radius);
        }
        return Array.from(p);
    });
}
const variations = new Set();
for (const seed of [0, 1, 2, 3, 42, 999999]) {
    const points = arrangement(seed);
    assert.equal(new Set(points.map(p => p.map(n => n.toFixed(7)).join(','))).size, layers.length);
    const expected = JSON.stringify(points);
    variations.add(expected);
    arrangement(123456);
    assert.equal(JSON.stringify(arrangement(seed)), expected, 'Reusing seed restores the exact permutation');
    arrangement(seed, true, true);
}
